it('called with wrapped Error when stream fails with a string', async () => {
  let receivedError: Error | undefined;
  const hooks: OrchestratorHooks = {
    onError: async (_session, error) => {
      receivedError = error;
    },
  };

  const orchestrator = createChatOrchestrator(
    createErrorProvider('rate limited string' as unknown as Error),
    promptBuilder,
    undefined,
    {hooks}
  );

  const caught = await orchestrator.processMessage(createSession('hello')).catch(e => e);

  expect({
    caught,
    isError: receivedError instanceof Error,
    message: receivedError?.message,
    cause: receivedError?.cause,
  }).toEqual({
    caught: 'rate limited string',
    isError: true,
    message: 'rate limited string',
    cause: 'rate limited string',
  });
});

it('called with wrapped Error when stream fails with an object', async () => {
  let receivedError: Error | undefined;
  const hooks: OrchestratorHooks = {
    onError: async (_session, error) => {
      receivedError = error;
    },
  };

  const reason = {code: 503, detail: 'upstream down'};
  const orchestrator = createChatOrchestrator(createErrorProvider(reason as unknown as Error), promptBuilder, undefined, {
    hooks,
  });

  const caught = await orchestrator.processMessage(createSession('hello')).catch(e => e);

  expect({
    caught,
    isError: receivedError instanceof Error,
    isMessageString: typeof receivedError?.message === 'string',
    isNotObjectObject: receivedError?.message !== '[object Object]',
    contains503: receivedError?.message?.includes('503'),
    cause: receivedError?.cause,
  }).toEqual({
    caught: reason,
    isError: true,
    isMessageString: true,
    isNotObjectObject: true,
    contains503: true,
    cause: reason,
  });
});

